{
  "name": "express-todo",
  "version": "1.0.0",
  "description": "Simple to-do list app with Express",
  "main": "server.js",
  "scripts": {
    "start": "node server.js",
    "dev": "node --watch server.js"
  },
  "engines": {
    "node": ">=18"
  },
  "dependencies": {
    "express": "^4.21.2"
  }
}

const express = require('express');
const path = require('path');
const fs = require('fs/promises');

const app = express();
const PORT = process.env.PORT || 3000;
const DATA_FILE = path.join(__dirname, 'data', 'todos.json');

app.use(express.json());
app.use(express.static(path.join(__dirname, 'public')));

async function ensureDataFile() {
  try {
    await fs.access(DATA_FILE);
  } catch {
    await fs.mkdir(path.dirname(DATA_FILE), { recursive: true });
    await fs.writeFile(DATA_FILE, '[]', 'utf8');
  }
}

async function readTodos() {
  const raw = await fs.readFile(DATA_FILE, 'utf8');
  return JSON.parse(raw);
}

async function writeTodos(todos) {
  await fs.writeFile(DATA_FILE, JSON.stringify(todos, null, 2), 'utf8');
}

function nextId(todos) {
  const max = todos.reduce((m, t) => Math.max(m, t.id), 0);
  return max + 1;
}

app.get('/api/todos', async (_req, res) => {
  try {
    const todos = await readTodos();
    res.json(todos);
  } catch (err) {
    res.status(500).json({ error: 'Failed to load todos' });
  }
});

app.post('/api/todos', async (req, res) => {
  const title = typeof req.body.title === 'string' ? req.body.title.trim() : '';
  if (!title) {
    return res.status(400).json({ error: 'Title is required' });
  }

  try {
    const todos = await readTodos();
    const todo = {
      id: nextId(todos),
      title,
      completed: false,
      createdAt: new Date().toISOString(),
    };
    todos.push(todo);
    await writeTodos(todos);
    res.status(201).json(todo);
  } catch (err) {
    res.status(500).json({ error: 'Failed to create todo' });
  }
});

app.patch('/api/todos/:id', async (req, res) => {
  const id = Number.parseInt(req.params.id, 10);
  if (Number.isNaN(id)) {
    return res.status(400).json({ error: 'Invalid id' });
  }

  try {
    const todos = await readTodos();
    const index = todos.findIndex((t) => t.id === id);
    if (index === -1) {
      return res.status(404).json({ error: 'Todo not found' });
    }

    const todo = todos[index];
    if (req.body.title !== undefined) {
      const title = String(req.body.title).trim();
      if (!title) {
        return res.status(400).json({ error: 'Title cannot be empty' });
      }
      todo.title = title;
    }
    if (req.body.completed !== undefined) {
      todo.completed = Boolean(req.body.completed);
    }

    await writeTodos(todos);
    res.json(todo);
  } catch (err) {
    res.status(500).json({ error: 'Failed to update todo' });
  }
});

app.delete('/api/todos/:id', async (req, res) => {
  const id = Number.parseInt(req.params.id, 10);
  if (Number.isNaN(id)) {
    return res.status(400).json({ error: 'Invalid id' });
  }

  try {
    const todos = await readTodos();
    const index = todos.findIndex((t) => t.id === id);
    if (index === -1) {
      return res.status(404).json({ error: 'Todo not found' });
    }
    todos.splice(index, 1);
    await writeTodos(todos);
    res.status(204).send();
  } catch (err) {
    res.status(500).json({ error: 'Failed to delete todo' });
  }
});

app.delete('/api/todos', async (req, res) => {
  const completedOnly = req.query.completed === 'true';
  try {
    let todos = await readTodos();
    if (completedOnly) {
      todos = todos.filter((t) => !t.completed);
    } else {
      todos = [];
    }
    await writeTodos(todos);
    res.status(204).send();
  } catch (err) {
    res.status(500).json({ error: 'Failed to clear todos' });
  }
});

ensureDataFile()
  .then(() => {
    app.listen(PORT, () => {
      console.log(`Todo app running at http://localhost:${PORT}`);
    });
  })
  .catch((err) => {
    console.error('Failed to start:', err);
    process.exit(1);
  });

:root {
  --bg: #0f1419;
  --surface: #1a2332;
  --border: #2d3a4f;
  --text: #e7ecf3;
  --muted: #8b9cb3;
  --accent: #5b9fd4;
  --accent-hover: #7ab3de;
  --done: #6bcf8a;
  --danger: #e07a7a;
  --radius: 10px;
  --font: system-ui, -apple-system, 'Segoe UI', sans-serif;
}

*,
*::before,
*::after {
  box-sizing: border-box;
}

body {
  margin: 0;
  min-height: 100vh;
  font-family: var(--font);
  background: radial-gradient(ellipse 120% 80% at 50% -20%, #1e3a5f 0%, var(--bg) 55%);
  color: var(--text);
  line-height: 1.5;
}

.app {
  max-width: 520px;
  margin: 0 auto;
  padding: 3rem 1.25rem 4rem;
}

.header h1 {
  margin: 0;
  font-size: 2rem;
  font-weight: 650;
  letter-spacing: -0.02em;
}

.subtitle {
  margin: 0.35rem 0 1.75rem;
  color: var(--muted);
  font-size: 0.9rem;
}

.add-form {
  display: flex;
  gap: 0.5rem;
  margin-bottom: 1.25rem;
}

.add-form input {
  flex: 1;
  padding: 0.75rem 1rem;
  border: 1px solid var(--border);
  border-radius: var(--radius);
  background: var(--surface);
  color: var(--text);
  font-size: 1rem;
}

.add-form input:focus {
  outline: 2px solid var(--accent);
  outline-offset: 1px;
}

.add-form button,
.todo-list button {
  cursor: pointer;
  font-family: inherit;
}

.add-form button {
  padding: 0.75rem 1.25rem;
  border: none;
  border-radius: var(--radius);
  background: var(--accent);
  color: #0a1628;
  font-weight: 600;
  font-size: 0.95rem;
}

.add-form button:hover {
  background: var(--accent-hover);
}

.toolbar {
  display: flex;
  align-items: center;
  justify-content: space-between;
  flex-wrap: wrap;
  gap: 0.5rem;
  margin-bottom: 0.75rem;
  font-size: 0.85rem;
  color: var(--muted);
}

.toolbar-actions {
  display: flex;
  gap: 0.75rem;
}

.link-btn {
  padding: 0;
  border: none;
  background: none;
  color: var(--accent);
  font-size: inherit;
  text-decoration: underline;
  text-underline-offset: 2px;
}

.link-btn:hover {
  color: var(--accent-hover);
}

.link-btn.danger {
  color: var(--danger);
}

.error {
  margin: 0 0 1rem;
  padding: 0.65rem 0.85rem;
  border-radius: var(--radius);
  background: rgba(224, 122, 122, 0.15);
  color: var(--danger);
  font-size: 0.9rem;
}

.todo-list {
  list-style: none;
  margin: 0;
  padding: 0;
  display: flex;
  flex-direction: column;
  gap: 0.5rem;
}

.todo-item {
  display: flex;
  align-items: center;
  gap: 0.75rem;
  padding: 0.85rem 1rem;
  border: 1px solid var(--border);
  border-radius: var(--radius);
  background: var(--surface);
  transition: border-color 0.15s;
}

.todo-item:hover {
  border-color: #3d4f6a;
}

.todo-item.completed .todo-title {
  color: var(--muted);
  text-decoration: line-through;
}

.todo-item input[type='checkbox'] {
  width: 1.15rem;
  height: 1.15rem;
  accent-color: var(--done);
  cursor: pointer;
}

.todo-title {
  flex: 1;
  word-break: break-word;
}

.todo-delete {
  padding: 0.35rem 0.6rem;
  border: 1px solid var(--border);
  border-radius: 6px;
  background: transparent;
  color: var(--muted);
  font-size: 0.8rem;
}

.todo-delete:hover {
  border-color: var(--danger);
  color: var(--danger);
}

.empty {
  text-align: center;
  color: var(--muted);
  margin-top: 2rem;
}

.empty[hidden],
.error[hidden],
.toolbar[hidden] {
  display: none !important;
}

const listEl = document.getElementById('todo-list');
const formEl = document.getElementById('add-form');
const inputEl = document.getElementById('title-input');
const emptyEl = document.getElementById('empty');
const errorEl = document.getElementById('error');
const toolbarEl = document.querySelector('.toolbar');
const countEl = document.getElementById('count');
const clearCompletedEl = document.getElementById('clear-completed');
const clearAllEl = document.getElementById('clear-all');

function showError(message) {
  errorEl.textContent = message;
  errorEl.hidden = !message;
}

async function api(path, options = {}) {
  const res = await fetch(path, {
    headers: { 'Content-Type': 'application/json', ...options.headers },
    ...options,
  });
  if (res.status === 204) return null;
  const data = await res.json().catch(() => ({}));
  if (!res.ok) {
    throw new Error(data.error || `Request failed (${res.status})`);
  }
  return data;
}

function render(todos) {
  listEl.innerHTML = '';
  const active = todos.filter((t) => !t.completed).length;
  const hasCompleted = todos.some((t) => t.completed);

  emptyEl.hidden = todos.length > 0;
  toolbarEl.hidden = todos.length === 0;
  countEl.textContent =
    todos.length === 0
      ? ''
      : `${active} item${active === 1 ? '' : 's'} left`;
  clearCompletedEl.hidden = !hasCompleted;

  for (const todo of todos) {
    const li = document.createElement('li');
    li.className = `todo-item${todo.completed ? ' completed' : ''}`;
    li.dataset.id = String(todo.id);

    const checkbox = document.createElement('input');
    checkbox.type = 'checkbox';
    checkbox.checked = todo.completed;
    checkbox.setAttribute('aria-label', `Mark "${todo.title}" as ${todo.completed ? 'incomplete' : 'complete'}`);

    const title = document.createElement('span');
    title.className = 'todo-title';
    title.textContent = todo.title;

    const del = document.createElement('button');
    del.type = 'button';
    del.className = 'todo-delete';
    del.textContent = 'Delete';

    checkbox.addEventListener('change', async () => {
      try {
        showError('');
        await api(`/api/todos/${todo.id}`, {
          method: 'PATCH',
          body: JSON.stringify({ completed: checkbox.checked }),
        });
        await load();
      } catch (err) {
        checkbox.checked = !checkbox.checked;
        showError(err.message);
      }
    });

    del.addEventListener('click', async () => {
      try {
        showError('');
        await api(`/api/todos/${todo.id}`, { method: 'DELETE' });
        await load();
      } catch (err) {
        showError(err.message);
      }
    });

    li.append(checkbox, title, del);
    listEl.appendChild(li);
  }
}

async function load() {
  const todos = await api('/api/todos');
  render(todos);
}

formEl.addEventListener('submit', async (e) => {
  e.preventDefault();
  const title = inputEl.value.trim();
  if (!title) return;
  try {
    showError('');
    await api('/api/todos', {
      method: 'POST',
      body: JSON.stringify({ title }),
    });
    inputEl.value = '';
    await load();
    inputEl.focus();
  } catch (err) {
    showError(err.message);
  }
});

clearCompletedEl.addEventListener('click', async () => {
  try {
    showError('');
    await api('/api/todos?completed=true', { method: 'DELETE' });
    await load();
  } catch (err) {
    showError(err.message);
  }
});

clearAllEl.addEventListener('click', async () => {
  if (!confirm('Delete all todos?')) return;
  try {
    showError('');
    await api('/api/todos', { method: 'DELETE' });
    await load();
  } catch (err) {
    showError(err.message);
  }
});

load().catch((err) => showError(err.message));

